#!/bin/sh
set -eu
umask 077
python3 -I -B - <<'INSTALL_APP_AFTER_GRANT_R29'
import base64,hashlib,os,platform,zlib
from pathlib import Path
assert os.geteuid()==0 and platform.system()=='Linux'
raw=zlib.decompress(base64.b64decode('',validate=True))
assert len(raw)==7592 and hashlib.sha256(raw).hexdigest()=='9eed12f34873bba0767e168d4ddde49f72fbf1df4c70bea5f0a6b86a4971c6b9'
p=Path('/root/t44-r9/app-after-grant-r29-01.py');assert p.parent.resolve()==p.parent
fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o444)
with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
print('R29_EXISTING_GRANT_CALLER_CONTINUATION_INSTALLED_ONLY')
INSTALL_APP_AFTER_GRANT_R29
